import{_ as a}from"./chunks/capture-picker.DtS6chX6.js";import{_ as r,o as e,c as o,a2 as l}from"./chunks/framework.CfwCq2QB.js";const g=JSON.parse('{"title":"网页导出（PDF / 长图）","description":"","frontmatter":{},"headers":[],"relativePath":"features/capture.md","filePath":"features/capture.md"}'),i={name:"features/capture.md"};function s(n,t,d,p,h,c){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="网页导出-pdf-长图" tabindex="-1">网页导出（PDF / 长图） <a class="header-anchor" href="#网页导出-pdf-长图" aria-label="Permalink to &quot;网页导出（PDF / 长图）&quot;">​</a></h1><p>一句话：把当前网页导出成和屏幕上一模一样的 PDF 或长图，样式、图片都不丢；也可以只框选页面上的某一块单独导出。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>打开要导出的网页，点工具栏图标打开弹窗，切到「功能」页，找到「导出网页」：</p><table tabindex="0"><thead><tr><th>按钮</th><th>效果</th></tr></thead><tbody><tr><td><strong>整页 PDF</strong></td><td>从头到尾滚动截取整个页面，拼成 PDF。PDF 里的文字可以选中、复制和搜索</td></tr><tr><td><strong>整页长图</strong></td><td>同样截取整页，保存为一张 PNG 长图</td></tr><tr><td><strong>选择区域</strong></td><td>弹窗关闭，在网页上用鼠标选中一块（卡片、表格、某段内容），导出成图片或 PDF，见下一节</td></tr></tbody></table><p>导出的文件直接保存到浏览器的下载目录，弹窗里会显示文件名。网页右键菜单里也有「将网页导出为 PDF」和「选择网页区域导出为图片 / PDF」。</p><h2 id="选择区域导出" tabindex="-1">选择区域导出 <a class="header-anchor" href="#选择区域导出" aria-label="Permalink to &quot;选择区域导出&quot;">​</a></h2><p>点「选择区域」后：</p><ol><li>鼠标移到页面上，蓝框会高亮当前元素，并标出它的尺寸</li><li>选得太小或太大时，按 <strong>↑</strong> 选父元素、<strong>↓</strong> 回到子元素</li><li>点击锁定，弹出操作条：<strong>导出图片</strong> / <strong>导出 PDF</strong> / <strong>重选</strong> / <strong>取消</strong>；<strong>Esc</strong> 随时退出</li></ol><p>导出的是这个元素的<strong>完整内容</strong>，不只是屏幕上能看到的那一部分：元素比一屏还高时会自动滚动分段截取再拼起来。</p><img src="'+a+'" alt="选择区域导出：页面上的卡片被蓝框选中，上方是「导出图片 / 导出 PDF / 重选 / 取消」操作条"><p><em>图：选择区域导出——选中卡片后弹出操作条。</em></p><h2 id="和「打印成-pdf」有什么不一样" tabindex="-1">和「打印成 PDF」有什么不一样 <a class="header-anchor" href="#和「打印成-pdf」有什么不一样" aria-label="Permalink to &quot;和「打印成 PDF」有什么不一样&quot;">​</a></h2><p>浏览器自带的打印会按纸张重新排版，经常丢背景、错位、把页面切成好几块。DevGo 的导出是按屏幕实际显示的样子截取：</p><ul><li>背景色、渐变、图片、圆角阴影都保留，和你看到的一致</li><li>吸顶导航、悬浮按钮这类固定元素只在第一屏出现，不会每一段都重复一遍</li><li>DevGo 自己的悬浮快捷栏、划词工具条等界面不会出现在导出结果里</li><li>整页 PDF 叠加了一层透明文字，可以选中、复制、搜索</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>浏览器内置页（<code>chrome://</code> 开头）、扩展商店等页面不允许扩展截图，按钮会提示当前页面不支持</li><li>超长页面截取需要几秒到几十秒，期间页面会自动滚动，请不要切换标签页</li><li>依靠滚动才加载内容的页面（无限下拉的信息流），只能导出已经加载出来的部分</li><li>不需要申请任何额外权限</li></ul>',17)])])}const _=r(i,[["render",s]]);export{g as __pageData,_ as default};
